shaderSource:
uniform float2 resolution;
uniform float2 touch;
uniform float time;

float sharpRing(float phase, float sharpness) {
  return pow(0.5 + 0.5 * cos(phase), sharpness);
}

half4 main(float2 xy) {
  float2 safeResolution = max(resolution, float2(1.0, 1.0));
  float2 uv = xy / safeResolution;
  float aspect = safeResolution.x / safeResolution.y;
  float2 touchUv = clamp(touch / safeResolution, float2(0.0, 0.0), float2(1.0, 1.0));

  // Aspect-correct distance keeps every wave circular on wide and tall surfaces.
  float2 delta = (uv - touchUv) * float2(aspect, 1.0);
  float distanceFromTouch = length(delta);
  float2 radial = delta / max(distanceFromTouch, 0.0001);

  // Constant-phase contours move outward as time increases: a train of expanding ripples.
  float phase = distanceFromTouch * 58.0 - time * 6.4;
  float nearFade = smoothstep(0.012, 0.055, distanceFromTouch);
  float farFade = 1.0 - smoothstep(0.48, 1.18, distanceFromTouch);
  float energy = nearFade * farFade * exp(-distanceFromTouch * 1.15);

  // Paired bright/dark bands read as a tiny refractive slope instead of a flat ring.
  float crest = sharpRing(phase, 10.0) * energy;
  float softCrest = sharpRing(phase + 0.42, 4.0) * energy;
  float trough = sharpRing(phase + 1.38, 8.0) * energy;
  float secondary = sharpRing(phase * 0.51 - 0.7, 12.0) * energy * 0.32;

  // A fixed upper-left light makes the ripple's lensing direction consistent.
  float directionalLight = clamp(dot(radial, normalize(float2(-0.62, -0.78))) * 0.5 + 0.5, 0.0, 1.0);
  float litCrest = crest * mix(0.35, 1.0, directionalLight);
  float shadedCrest = crest * mix(1.0, 0.28, directionalLight);

  // Touch impact and a short glossy wake make interaction feel wet, not mechanical.
  float impactPulse = 0.55 + 0.45 * sin(time * 3.1);
  float impact = exp(-distanceFromTouch * distanceFromTouch * 92.0) * impactPulse;
  float wake = exp(-pow(delta.x * 1.8 + delta.y * 0.52, 2.0) * 36.0);
  wake *= exp(-distanceFromTouch * 4.2) * 0.42;

  // Fine caustics remain subtle so text above the material stays readable.
  float causticA = 0.5 + 0.5 * sin(uv.x * 13.0 + uv.y * 7.0 - time * 0.55);
  float causticB = 0.5 + 0.5 * sin(uv.x * -8.0 + uv.y * 15.0 + time * 0.38);
  float caustic = pow(clamp(causticA * causticB, 0.0, 1.0), 5.0) * 0.055;

  // Quiet glass edge so the water remains visible when no touch has occurred yet.
  float2 edgeDistance = min(uv, float2(1.0, 1.0) - uv);
  float edge = min(edgeDistance.x * aspect, edgeDistance.y);
  float rim = 1.0 - smoothstep(0.0, 0.055, edge);
  float innerRim = smoothstep(0.025, 0.075, edge) * (1.0 - smoothstep(0.075, 0.16, edge));

  // Slight wavelength separation gives the brightest crests a believable water prism.
  float redWave = sharpRing(phase - 0.075, 10.0) * energy;
  float greenWave = sharpRing(phase, 10.0) * energy;
  float blueWave = sharpRing(phase + 0.09, 10.0) * energy;
  half3 spectralCrest = half3(redWave, greenWave, blueWave);

  half3 color = mix(half3(0.68, 0.86, 0.98), half3(0.94, 0.985, 1.0), 0.68 + 0.20 * (1.0 - uv.y));
  color += half3(1.0, 1.0, 1.0) * (litCrest * 0.78 + softCrest * 0.16 + impact * 0.38);
  color += half3(0.48, 0.78, 1.0) * (secondary * 0.44 + wake * 0.18 + caustic);
  color += spectralCrest * 0.085;
  color += half3(0.86, 0.96, 1.0) * (rim * 0.30 + innerRim * 0.13);
  color *= 1.0 - shadedCrest * 0.16 - trough * 0.085;

  // The blurred backdrop remains the material; the shader contributes only optical relief.
  float alpha = 0.045 + rim * 0.13 + innerRim * 0.035;
  alpha += litCrest * 0.21 + trough * 0.055 + secondary * 0.06;
  alpha += impact * 0.10 + wake * 0.04 + caustic * 0.45;

  return half4(clamp(color, half3(0.0), half3(1.0)), clamp(alpha, 0.0, 0.56));
}
